def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    patterns = []
    for r in {0, h - 1}:
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            patterns.append(grid[r][start:c])
    for r in range(1, h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            for pattern in patterns:
                if color in pattern:
                    start = c - pattern.index(color)
                    for i, value in enumerate(pattern):
                        x = start + i
                        if 0 <= x < w:
                            out[r][x] = value
                    break
    return out
